    preloader.tasks.add(first);
    preloader.tasks.add(second);
    preloader.tasks.add(third);
    PreloaderService service = new ConcurrentPreloaderService(Executors.newFixedThreadPool(5), preloader);
    service.preload((Gadget) null);
