    // Note that relative URLs are fully resolved
    assertEquals(wrapper.getValue("//link[1]/@href"), "http://www.test.com/dir/concat?" + "rewriteMime=text/css&gadget=http%3A%2F%2Fwww.example.org%2Fdir%2Fg.xml&fp=1150739864&refresh=3600" + "&1=http%3A%2F%2Fwww.example.org%2Flinkedstyle1.css" + "&2=http%3A%2F%2Fwww.example.org%2Flinkedstyle3.css" + "&3=http%3A%2F%2Fwww.example.org%2Fimportedstyle1.css" + "&4=http%3A%2F%2Fwww.example.org%2Fimportedstyle3.css" + "&5=http%3A%2F%2Fwww.example.org%2Fimportedstyle4.css");
    // Untouched link target
    assertEquals("http://www.example.org/excluded/linkedstyle2.css", wrapper.getValue("//link[2]/@href"));
